import { test, expect } from '@playwright/test';

test.describe('Accessibility - Icon Buttons', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should have accessible names for all icon buttons', async ({ page }) => {
    const iconButtons = await page.getByRole('button', { name: /icon/i });
    for (const button of iconButtons) {
      const accessibleName = await button.evaluate(el => el.getAttribute('aria-label') || el.textContent);
      expect(accessibleName).toBeTruthy();
    }
  });

  test('should ensure all icon buttons are labeled correctly', async ({ page }) => {
    const iconButtons = await page.getByRole('button', { name: /icon/i });
    for (const button of iconButtons) {
      const accessibleName = await button.evaluate(el => el.getAttribute('aria-label') || el.textContent);
      expect(accessibleName).not.toBe('');
    }
  });
});
